// Domains that are job boards, social networks or directories, not company websites
const notCompanyDomains = [
  'linkedin.com', 'indeed.com', 'infojobs.net', 'glassdoor.com', 'facebook.com',
  'instagram.com', 'twitter.com', 'x.com', 'youtube.com', 'wikipedia.org'
];

// Addresses that nobody reads
const unusableStarts = ['noreply', 'no-reply', 'donotreply', 'do-not-reply'];

// Turn a web address into a plain domain, or an empty text if it is not valid
function getDomain(address) {
  // Take the text between "http://" or "https://" and the next "/", "?", "#" or ":"
  const match = String(address || '').trim().match(/^https?:\/\/([^\/?#:]+)/i);
  if (!match) return '';
  const host = match[1].toLowerCase();
  if (!host.includes('.')) return '';
  return host.replace(/^www\./, '');
}

const lead = $json;
const domain = getDomain(lead.websiteUrl);
let email = String(lead.contactEmail || '').trim().toLowerCase();
let emailSource = String(lead.emailSourceUrl || '').trim();

// An address is kept only if it looks valid, someone reads it,
// and we know the page where it was seen.
// Otherwise we clear it (with its source), and the research stage looks for a better one.
// A missing address never rejects the lead: Verify Address does that later if research finds nothing.
const looksValid = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
const isReadable = !unusableStarts.some(s => email.startsWith(s));
const hasSource = getDomain(emailSource) !== '';
if (!(looksValid && isReadable && hasSource)) {
  email = '';
  emailSource = '';
}

// Run the checks on the company in order. The first one that fails gives the reason.
let reason = '';
if (domain === '') {
  reason = 'no website';
} else if (notCompanyDomains.some(d => domain === d || domain.endsWith('.' + d))) {
  reason = 'not a company website';
} else if (lead.language !== 'Spanish' && lead.language !== 'English') {
  // The writer only knows these two languages
  reason = 'invalid language';
}

// Return the same lead plus the fields this step is responsible for
return {
  json: {
    ...lead,
    contactEmail: email,
    emailSourceUrl: emailSource,
    domain: domain,
    status: reason === '' ? 'found' : 'rejected',
    statusReason: reason,
    emailVerified: false
  }
};
